import{c as t,Q as a,j as i,m as r}from"./chunks/framework.BPKcPtvA.js";const m=JSON.parse('{"title":"OTP security","description":"How email OTPs are generated, stored, rate-limited, and locked out.","frontmatter":{"title":"OTP security","description":"How email OTPs are generated, stored, rate-limited, and locked out."},"headers":[],"relativePath":"security/otp-security.md","filePath":"security/otp-security.md"}'),o={name:"security/otp-security.md"};function s(n,e,c,d,l,u){return a(),i("div",null,[...e[0]||(e[0]=[r('<h2 id="code-generation" tabindex="-1">Code generation <a class="header-anchor" href="#code-generation" aria-label="Permalink to &quot;Code generation&quot;">​</a></h2><p>Email OTPs are 6-digit codes generated using <code>crypto/rand</code>, Go&#39;s cryptographically secure random number generator. Using <code>crypto/rand</code> (rather than the standard <code>math/rand</code>) means the codes are unpredictable even if an attacker knows when they were generated.</p><p>Each code is associated with a specific user and has a 10-minute expiry. Codes are marked used on first successful verification and cannot be reused.</p><h2 id="storage" tabindex="-1">Storage <a class="header-anchor" href="#storage" aria-label="Permalink to &quot;Storage&quot;">​</a></h2><p>OTP codes are stored as HMAC-SHA256 digests keyed with the application&#39;s <code>SECRET_KEY</code>, not as plaintext. When verifying a submitted code, GateKeeper computes the HMAC of the submitted value and compares it to the stored digest using a constant-time comparison.</p><p>This means a database dump without <code>SECRET_KEY</code> cannot be used to reconstruct valid codes or brute-force the 1,000,000-possibility space without also knowing the key.</p><h2 id="issuance-rate-limiting" tabindex="-1">Issuance rate limiting <a class="header-anchor" href="#issuance-rate-limiting" aria-label="Permalink to &quot;Issuance rate limiting&quot;">​</a></h2><p>A user can request at most 3 new OTP codes within any 10-minute window. If they request more - for example by repeatedly clicking &quot;resend&quot; - they receive an error and must wait for the window to reset. This prevents using the issuance endpoint to overwhelm a mail server or probe for account existence.</p><h2 id="verification-lockout" tabindex="-1">Verification lockout <a class="header-anchor" href="#verification-lockout" aria-label="Permalink to &quot;Verification lockout&quot;">​</a></h2><p>To prevent an attacker from guessing a 6-digit code:</p><ul><li>After 5 failed OTP attempts within a 10-minute window, the account is locked for 10 minutes.</li><li>The lockout window slides: it resets when 10 minutes have passed since the first failed attempt.</li></ul><p>This limits an attacker to roughly 5 guesses per 10 minutes, making systematic brute-force impractical for the duration the code is valid.</p><h2 id="email-delivery" tabindex="-1">Email delivery <a class="header-anchor" href="#email-delivery" aria-label="Permalink to &quot;Email delivery&quot;">​</a></h2><p>GateKeeper sends OTPs over SMTP using the configured mail server. The email contains the code and a note that it expires in 10 minutes.</p><p>No links are included in OTP emails - only the raw code. This prevents link preview bots from consuming the OTP before the user sees it.</p>',15)])])}const p=t(o,[["render",s]]);export{m as __pageData,p as default};
